#![cfg(feature = "cli")]

//! Regression tests that pin the Rust port to the behaviour of the C
//! implementation.
//!
//! `tests/expected/t1_q1.txt` is generated by `scripts/gen_expected.sh`, which
//! runs `ksw2/ksw2-test` (the original C code) on `ksw2/test/{t1,q1}.fa` for
//! every algorithm / flag combination. This test replays the very same cases
//! with the Rust binary and requires a byte-identical result (NUL bytes aside,
//! since `cli.c` prints a NUL for the `N` CIGAR operator).

use std::process::Command;

const EXPECTED: &str = include_str!("expected/t1_q1.txt");

fn run_case(algo: &str, flags: &[&str]) -> String {
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_ksw2-test"));
    cmd.arg("-t").arg(algo);
    for f in flags {
        cmd.arg(f);
    }
    cmd.arg("ksw2/test/t1.fa").arg("ksw2/test/q1.fa");
    let out = cmd.output().expect("failed to run ksw2-test");
    assert!(
        out.status.success(),
        "ksw2-test {algo} {flags:?} failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let mut s = String::from_utf8_lossy(&out.stdout).into_owned();
    s.push_str(&String::from_utf8_lossy(&out.stderr));
    s
}

fn split_marker(line: &str) -> Option<(&str, Vec<String>)> {
    let rest = line.strip_prefix("@@ ")?;
    let (algo, flags) = rest.split_once(" |")?;
    let flags = flags
        .trim_end_matches('|')
        .split_whitespace()
        .map(|s| s.to_string())
        .collect();
    Some((algo, flags))
}

#[test]
fn matches_c_reference_output() {
    let mut rebuilt = String::new();
    let mut pending: Option<(String, Vec<String>)> = None;
    for line in EXPECTED.lines() {
        if let Some((algo, flags)) = split_marker(line) {
            if let Some((a, fl)) = pending.take() {
                let fl: Vec<&str> = fl.iter().map(|s| s.as_str()).collect();
                rebuilt.push_str(&run_case(&a, &fl));
            }
            rebuilt.push_str(line);
            rebuilt.push('\n');
            pending = Some((algo.to_string(), flags));
        }
    }
    if let Some((a, fl)) = pending.take() {
        let fl: Vec<&str> = fl.iter().map(|s| s.as_str()).collect();
        rebuilt.push_str(&run_case(&a, &fl));
    }

    let expected = EXPECTED.replace('\0', "");
    let rebuilt = rebuilt.replace('\0', "");
    if rebuilt != expected {
        for (i, (a, b)) in expected.lines().zip(rebuilt.lines()).enumerate() {
            if a != b {
                panic!("mismatch on line {}:\n  C: {a}\n  R: {b}", i + 1);
            }
        }
        panic!(
            "output length differs: C {} vs Rust {}",
            expected.len(),
            rebuilt.len()
        );
    }
}
